create or replace function public.rental_get_tenancy_financial_balances(p_tenancy_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if auth.uid() is null or not exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=p_tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'You are not authorized for this tenancy'; end if;
 select jsonb_build_object(
 'charges',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'description',c.description,'due_date',c.due_date,'amount',c.amount,'allocated_amount',coalesce((select sum(a.amount) from public.rental_financial_allocations a where a.charge_id=c.id),0),'outstanding_amount',c.amount-coalesce((select sum(a.amount) from public.rental_financial_allocations a where a.charge_id=c.id),0)) order by c.due_date nulls last,c.created_at) from public.rental_financial_charges c where c.tenancy_id=p_tenancy_id),'[]'::jsonb),
 'payments',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'received_date',p.received_date,'payment_reference',p.payment_reference,'amount',p.amount,'allocated_amount',coalesce((select sum(a.amount) from public.rental_financial_allocations a where a.payment_id=p.id),0),'unapplied_amount',p.amount-coalesce((select sum(a.amount) from public.rental_financial_allocations a where a.payment_id=p.id),0)) order by p.received_date desc,p.created_at desc) from public.rental_financial_payments p where p.tenancy_id=p_tenancy_id),'[]'::jsonb),
 'adjustments',coalesce((select jsonb_agg(jsonb_build_object('id',j.id,'adjustment_type',j.adjustment_type,'effective_date',j.effective_date,'amount',j.amount,'reason',j.reason,'correction_request_id',j.correction_request_id) order by j.effective_date desc,j.created_at desc) from public.rental_financial_adjustments j where j.tenancy_id=p_tenancy_id),'[]'::jsonb),
 'summary',jsonb_build_object('charge_total',coalesce((select sum(amount) from public.rental_financial_charges where tenancy_id=p_tenancy_id),0),'allocated_total',coalesce((select sum(amount) from public.rental_financial_allocations where tenancy_id=p_tenancy_id),0),'debit_adjustment_total',coalesce((select sum(amount) from public.rental_financial_adjustments where tenancy_id=p_tenancy_id and adjustment_type='debit'),0),'credit_adjustment_total',coalesce((select sum(amount) from public.rental_financial_adjustments where tenancy_id=p_tenancy_id and adjustment_type='credit'),0),'net_outstanding_amount',coalesce((select sum(amount) from public.rental_financial_charges where tenancy_id=p_tenancy_id),0)-coalesce((select sum(amount) from public.rental_financial_allocations where tenancy_id=p_tenancy_id),0)+coalesce((select sum(amount) from public.rental_financial_adjustments where tenancy_id=p_tenancy_id and adjustment_type='debit'),0)-coalesce((select sum(amount) from public.rental_financial_adjustments where tenancy_id=p_tenancy_id and adjustment_type='credit'),0))
 ) into result;
 return result;
end; $$;
revoke execute on function public.rental_get_tenancy_financial_balances(uuid) from public,anon;
grant execute on function public.rental_get_tenancy_financial_balances(uuid) to authenticated;;
